const p = msg.payload || {};
const elev = Number(p.altitudeDegrees);
const nowTs = Number(p.ts);
const outdoor = Number(msg.outdoor);
const luxMax = Number(msg.luxMax);

if (!Number.isFinite(elev) || !Number.isFinite(nowTs)) {
    node.status({ fill: 'red', shape: 'ring', text: 'no sun data' });
    return null;
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const smooth = (v, lo, hi) => {
    const t = clamp01((v - lo) / (hi - lo));
    return t * t * (3 - 2 * t);
};
const num = (name, dflt) => {
    const v = Number(env.get(name));
    return Number.isFinite(v) ? v : dflt;
};

const H = 3600000;
const times = p.times || {};
const sunsetTs = times.sunsetStart ? Number(times.sunsetStart.ts) : NaN;
const sunriseTs = times.sunriseEnd ? Number(times.sunriseEnd.ts) : NaN;
if (!Number.isFinite(sunsetTs) || !Number.isFinite(sunriseTs)) {
    node.status({ fill: 'red', shape: 'ring', text: 'no sunrise/sunset' });
    return null;
}

let lastSunset = sunsetTs;
if (lastSunset > nowTs) lastSunset -= 24 * H;
let nextSunrise = sunriseTs;
if (nextSunrise < nowTs) nextSunrise += 24 * H;

const hAfterSunset = (nowTs - lastSunset) / H;
const hBeforeSunrise = (nextSunrise - nowTs) / H;

const darkBase = (evH, moH) => {
    const evening = clamp01(1 - hAfterSunset / Math.max(0.1, evH));
    const morning = clamp01(1 - hBeforeSunrise / Math.max(0.1, moH));
    return 0.85 * Math.max(evening, morning);
};

let luxNorm = 0;
const luxOk = Number.isFinite(outdoor) && Number.isFinite(luxMax) && luxMax > 0;
if (luxOk) luxNorm = clamp01(outdoor / luxMax);

let gBase;
if (elev > 0) {
    gBase = 0.85 + 0.15 * smooth(elev, 0, 25);
} else {
    gBase = darkBase(num('EVENING_HOURS_GAIN', 4), num('MORNING_HOURS_GAIN', 1.5));
}

const Bmax = num('DAYLIGHT_COMP_MAX', 0.5);
const B = luxOk ? Bmax * smooth(elev, 0, 35) : 0;
const gain01 = clamp01(gBase * (1 - B) + (1 - luxNorm) * B);

const gMin = num('GAIN_MIN', 30);
const gMax = num('GAIN_MAX', 100);
const gainPct = Math.round(gMin + gain01 * (gMax - gMin));

let tBase;
if (elev > 0) {
    tBase = 0.85 + 0.15 * smooth(elev, 5, 25);
} else {
    tBase = darkBase(num('EVENING_HOURS_TEMP', 3), num('MORNING_HOURS_TEMP', 1.5));
}

const inflMax = num('TEMP_OUTDOOR_INFLUENCE', 0.15);
const infl = luxOk ? inflMax * smooth(elev, 0, 35) : 0;
const temp01 = clamp01(tBase + (luxNorm - tBase) * infl);

const tMin = num('TEMP_MIN', 2200);
const tMax = num('TEMP_MAX', 4000);
const kelvin = Math.round(tMin + temp01 * (tMax - tMin));

msg.debug = {
    elev: Math.round(elev * 10) / 10,
    hAfterSunset: Math.round(hAfterSunset * 100) / 100,
    hBeforeSunrise: Math.round(hBeforeSunrise * 100) / 100,
    luxNorm: Math.round(luxNorm * 100) / 100,
    gBase: Math.round(gBase * 100) / 100,
    B: Math.round(B * 100) / 100,
    tBase: Math.round(tBase * 100) / 100,
    infl: Math.round(infl * 100) / 100
};

node.status({ fill: 'green', shape: 'dot', text: gainPct + '% / ' + kelvin + 'K, elev ' + elev.toFixed(1) });

return [
    { payload: gainPct, debug: msg.debug },
    { payload: kelvin, debug: msg.debug }
];

var newmsg = JSON.parse(JSON.stringify(msg));
newmsg.payload.times_of_day = {};

const processTimeOfDay = function(nme, obj, name_start, name_end) {
    var ret = {};
    ret.name  = nme;
    ret.start = obj.times[name_start].ts;
    ret.end   = obj.times[name_end].ts;
    ret.perc  = (obj.ts - ret.start) / (ret.end - ret.start);


    // to cover range starting before midnight and ending after it.
    if (ret.start > ret.end)
    {
        var a;

        // before midnight
        if (ret.start < obj.ts) 
        {
            a = new Date(ret.end);
            a.setUTCDate(a.getUTCDate() + 1);
            ret.end = a.getTime();


        }
        else if (ret.end > obj.ts) 
        {
            a = new Date(ret.start);
            a.setUTCDate(a.getUTCDate() - 1);
            ret.start = a.getTime();

        }

    }

    ret.perc  = (obj.ts - ret.start) / (ret.end - ret.start);

    obj.times_of_day[nme] = ret;
    if (ret.start <= obj.ts && obj.ts < ret.end ) obj.times_of_day.active = ret;
}


processTimeOfDay('night', newmsg.payload, "astronomicalDusk", "astronomicalDawn");
processTimeOfDay('morning', newmsg.payload, "astronomicalDawn", "goldenHourDawnEnd");
processTimeOfDay('day', newmsg.payload, "goldenHourDawnEnd", "sunsetStart");
processTimeOfDay('evening', newmsg.payload, "sunsetStart", "astronomicalDusk");


return newmsg;

// ================= INPUT =================
const sunCurve = Number(msg.sunCurve);
const outdoorLog = Number(msg.outdoor);
const altitude = Number(msg.payload?.altitudeDegrees);

// ================= VALIDATION =================
if (!Number.isFinite(sunCurve)) return null;
if (!Number.isFinite(outdoorLog)) return null;
if (!Number.isFinite(altitude)) return null;

// ================= LUX MODEL =================
// Настрой под реальный диапазон outdoorLog
const luxMin = 0;
const luxMax = Number(msg.luxMax);

// clamp
const luxClamped = Math.max(luxMin, Math.min(luxMax, outdoorLog));
let luxNorm = (luxClamped - luxMin) / (luxMax - luxMin);

// ярко на улице → меньше света внутри
const luxModel = 1 - luxNorm;

// ================= SUN ALTITUDE MODEL =================
const altMin = 0;     // горизонт
const altMax = 35;    // средняя высота солнца
const Bmax = 0.5;     // максимум влияния lux

let B = 0;

if (altitude <= altMin) {
    B = 0;
}
else if (altitude >= altMax) {
    B = Bmax;
}
else {
    const t = (altitude - altMin) / (altMax - altMin);

    // Более физичная кривая через синус
    const tSmooth = Math.sin(t * Math.PI / 2);

    B = Bmax * tSmooth;
}

const A = 1 - B;

// ================= FINAL MIX =================
let out = (sunCurve * A) + (luxModel * B);

// clamp 0..1
out = Math.max(0, Math.min(1, out));

// ================= OUTPUT =================
msg.payload = out;

msg.debug = {
    sunCurve,
    luxModel,
    altitude,
    A,
    B
};

return msg;

// ================= INPUT =================
const base = Number(msg.sunCurve);               // 0..1 после spline
const outdoorLog = Number(msg.outdoor);
const altitude = Number(msg.payload?.altitudeDegrees);

// ================= VALIDATION =================
if (!Number.isFinite(base)) return null;
if (!Number.isFinite(outdoorLog)) return null;
if (!Number.isFinite(altitude)) return null;

// ================= LUX NORMALIZATION =================
const luxMin = 0;
const luxMax = Number(msg.luxMax);

if (!Number.isFinite(luxMax) || luxMax <= luxMin) return null;

const luxClamped = Math.max(luxMin, Math.min(luxMax, outdoorLog));
const luxNorm = (luxClamped - luxMin) / (luxMax - luxMin);

// НЕ инвертируем — как ты и хотел
const luxModel = luxNorm;

// ================= ALTITUDE MODEL =================
const altMin = 0;
const altMax = 35;
const influenceMax = 0.15;

let influence = 0;

if (altitude <= altMin) {
    influence = 0;
}
else if (altitude >= altMax) {
    influence = influenceMax;
}
else {
    const t = (altitude - altMin) / (altMax - altMin);
    const tSmooth = Math.sin(t * Math.PI / 2);
    influence = influenceMax * tSmooth;
}

// ================= FINAL (FIXED MODEL) =================
// Вместо умножения — controlled blend к luxModel
let out = base + (luxModel - base) * influence;

// clamp 0..1
out = Math.max(0, Math.min(1, out));

// ================= OUTPUT =================
msg.payload = out;

msg.debug = {
    base,
    altitude,
    luxModel,
    influence,
    delta: (luxModel - base),
    appliedShift: (luxModel - base) * influence
};

return msg;

// Безопасно получаем массив entity_id
const entities = msg.payload;

if (!Array.isArray(entities)) {
    node.error("msg.payload должен быть массивом");
    return null;
}

// Получаем все состояния из Home Assistant
const ha = global.get('homeassistant');

if (!ha || !ha.homeAssistant || !ha.homeAssistant.states) {
    node.error("Не найден глобальный объект homeassistant. Убедитесь, что Node-RED интеграция активна");
    return null;
}

// Проверка: все ли состояния НЕ 'on'
const allOff = entities.every(id => {
    const state = ha.homeAssistant.states[id];
    return !state || state.state == 'off' || state.state == 'unavailable' ;
});

// Возвращаем результат
msg.enable = allOff;
return msg;

const start = new Date(msg.start_date);   // ISO строка из input_datetime
const now = new Date();

const elapsedDays = (now.getTime() - start.getTime()) / 86400000;
if (!isFinite(elapsedDays) || elapsedDays <= 0) return null;

const startMeter = Number(msg.start_meter);
const currentVal = Number(msg.current_meter);

let used;
if (currentVal && startMeter) {
  used = currentVal - startMeter;
}

if (!isFinite(used) || used < 0) return null;

const avg = used / elapsedDays;

msg.payload = Number(avg.toFixed(4));

msg.attributes = {
  used_kwh: Number(used.toFixed(2)),
  elapsed_days: Number(elapsedDays.toFixed(3)),
  updated_at: now.toISOString(),
  avg_year: Number(avg.toFixed(4)) * 365
};

return msg;

// ===== КОНФИГ =====
const ENTRY_HOLD_MIN = 5;        // условия входа (сон) держатся N мин
const BED_EMPTY_MIN = 10;        // пустая кровать N мин до выхода (защита от туалета)
const AWAY_HOLD_MIN = 5;         // никого дома N мин -> away
const OVERRIDE_HOURS = 8;        // длительность ручного override
const NIGHT_START = 21;          // окно входа (сон): с 21:00
const NIGHT_END = 4;             // окно входа (сон): до 04:00
const MORNING_EXIT = 10;         // утренний выход после 10:00

// entity_id
const E_BED = 'binary_sensor.pressure_bed_group_binary';
const E_LIGHT = 'switch.wall_switch_bedroom';
const E_RADAR = 'binary_sensor.esphome_radar_bedroom_occupancy_ld241x';
const E_SWITCH = 'switch.switch_sleep_mode';
const E_HOME = 'binary_sensor.presence_anyone_home';

// ===== ЧТЕНИЕ СОСТОЯНИЙ HA =====
const ha = global.get('homeassistant');
if (!ha || !ha.homeAssistant || !ha.homeAssistant.states) {
    node.error('homeassistant global недоступен');
    return null;
}
const states = ha.homeAssistant.states;
const st = (id) => (states[id] ? states[id].state : 'unavailable');

const bedOn    = st(E_BED) === 'on';
const lightOn  = st(E_LIGHT) === 'on';
const radarOn  = st(E_RADAR) === 'on';
const switchOn = st(E_SWITCH) === 'on';
const homeRaw  = st(E_HOME);
const homeOn   = homeRaw === 'on';
const homeKnown = homeRaw === 'on' || homeRaw === 'off'; // не доверяем unavailable/unknown

// ===== ПРОВЕРКА AUTOMATION MASTER =====
const automationsEnable = global.get('automationsEnable', 'file');
if (automationsEnable === false) {
    return null; // автоматика выключена — ничего не трогаем
}

const now = Date.now();
const hour = new Date().getHours();

// ===== CONTEXT =====
let s = flow.get('sleepFSM') || {
    state: 'AWAKE',
    reason: null,          // 'sleep' | 'away' — почему вошли в ASLEEP
    entryStart: null,      // таймер условий входа (сон)
    bedEmptyStart: null,   // таймер пустой кровати
    awayStart: null,       // таймер отсутствия дома
    overrideUntil: 0,      // дедлайн ручного override
    lastAutoWrite: null,   // последнее значение, записанное автоматикой
};

const topic = msg.topic || 'tick';

// ===== ДЕТЕКТ РУЧНОГО НАЖАТИЯ =====
if (topic === 'switch') {
    const wrote = s.lastAutoWrite;
    if (wrote === null || (switchOn ? 'on' : 'off') !== wrote) {
        s.overrideUntil = now + OVERRIDE_HOURS * 3600 * 1000;
        node.warn('Ручной override на ' + OVERRIDE_HOURS + 'ч');
    }
    s.state = switchOn ? 'ASLEEP' : 'AWAKE';
    s.reason = switchOn ? 'manual' : null;
    s.lastAutoWrite = null;
    flow.set('sleepFSM', s);
    return null;
}

const overrideActive = now < s.overrideUntil;
const inNightWindow = (hour >= NIGHT_START) || (hour < NIGHT_END);

// ===== ЛОГИКА ПЕРЕХОДОВ =====
let desired = null;       // null = не менять, true = ASLEEP, false = AWAKE
let newReason = s.reason;

if (!overrideActive) {
    if (s.state === 'AWAKE') {
        // --- ВХОД 1: ОТСУТСТВИЕ ДОМА (приоритетнее, проверяем первым) ---
        if (homeKnown && !homeOn) {
            if (s.awayStart === null) s.awayStart = now;
            const away = (now - s.awayStart) / 60000;
            if (away >= AWAY_HOLD_MIN) {
                desired = true;
                newReason = 'away';
            }
        } else {
            s.awayStart = null;
        }

        // --- ВХОД 2: СОН (только если не ушли по away) ---
        if (desired === null) {
            const entryCond = bedOn && !lightOn && inNightWindow && homeOn;
            if (entryCond) {
                if (s.entryStart === null) s.entryStart = now;
                const held = (now - s.entryStart) / 60000;
                if (held >= ENTRY_HOLD_MIN) {
                    desired = true;
                    newReason = 'sleep';
                }
            } else {
                s.entryStart = null;
            }
        }
    } else if (s.state === 'ASLEEP') {
        if (s.reason === 'away') {
            // --- ВЫХОД ИЗ AWAY: кто-то вернулся домой ---
            if (homeOn) {
                desired = false;
            }
        } else {
            // --- ВЫХОД ИЗ СНА (reason 'sleep' или 'manual') ---
            // 1) свет включили — мгновенно
            if (lightOn) {
                desired = false;
            }
            // 2) пустая кровать дольше N мин (радар продлевает)
            else if (!bedOn) {
                if (radarOn) {
                    s.bedEmptyStart = null;
                } else {
                    if (s.bedEmptyStart === null) s.bedEmptyStart = now;
                    const empty = (now - s.bedEmptyStart) / 60000;
                    if (empty >= BED_EMPTY_MIN) desired = false;
                }
            }
            // 3) кровать снова занята — сброс
            else {
                s.bedEmptyStart = null;
            }
            // 4) утренний выход
            if (hour >= MORNING_EXIT && !bedOn) desired = false;

            // 5) если все ушли из дома во сне — переклеить причину на away,
            //    чтобы выход произошёл по возвращению, а не по свету/кровати
            if (homeKnown && !homeOn) {
                newReason = 'away';
                desired = null; // остаёмся в ASLEEP
            }
        }
    }
}

// ===== ПРИМЕНЕНИЕ РЕШЕНИЯ =====
let out = null;
if (desired === true && s.state !== 'ASLEEP') {
    s.state = 'ASLEEP';
    s.reason = newReason;
    s.entryStart = null;
    s.bedEmptyStart = null;
    s.awayStart = null;
    if (!switchOn) {
        s.lastAutoWrite = 'on';
        out = { payload: true };
    }
} else if (desired === false && s.state !== 'AWAKE') {
    s.state = 'AWAKE';
    s.reason = null;
    s.entryStart = null;
    s.bedEmptyStart = null;
    s.awayStart = null;
    if (switchOn) {
        s.lastAutoWrite = 'off';
        out = { payload: false };
    }
} else {
    // решения нет, но причина могла смениться (sleep -> away во сне)
    s.reason = newReason;
}

flow.set('sleepFSM', s);

node.status({
    fill: s.state === 'ASLEEP' ? 'blue' : 'green',
    shape: 'dot',
    text: `${s.state}${s.reason ? '/' + s.reason : ''}${overrideActive ? ' (override)' : ''} home:${homeOn?1:0} bed:${bedOn?1:0}`
});

return out;

// ================= Sleep Mode FSM v2 =================
// Вся логика определения сна — в этом узле.
// Состояние хранится в flow context (file) и переживает рестарты NR/HA.
// Требуется: в настройках сервера HA включить "Enable global context store".

const CFG = {
    BED:           'binary_sensor.pressure_bed_group_binary',
    BEDROOM_LIGHT: 'switch.wall_switch_bedroom',
    BEDROOM_RADAR: 'binary_sensor.esphome_radar_bedroom_occupancy_ld241x',
    ANYONE_HOME:   'binary_sensor.presence_anyone_home',
    SLEEP_SWITCH:  'switch.switch_sleep_mode',
    ILLUM:         'binary_sensor.illuminance_all_light',
    SUN:           'sun.sun',
    ACTIVITY: [                                   // активность вне спальни
        'binary_sensor.esphome_radar_kitchen_occupancy',
        'binary_sensor.esphome_radar_bathroom_occupancy',
        'binary_sensor.esphome_radar_livingroom_occupancy',
        'binary_sensor.presence_hall'
    ],

    // скоринг (0..3) -> требуемое непрерывное удержание условий, мин
    HOLD_BY_SCORE: { 3: 5, 2: 20, 1: 45, 0: 90 },

    QUIET_MIN: 15,            // "тишина": нет активности вне спальни дольше N мин
    DARK_LUX: 20,             // порог темноты в доме, lx
    LUX_ATTRS: ['median', 'illuminance', 'median_lux', 'lux', 'light_level'],

    BED_GAP_S: 60,            // провалы мата короче N сек игнорируем (перевернулся)
    BED_EMPTY_EXIT_MIN: 10,   // выход: кровать непрерывно пуста N мин
    RADAR_EXTEND_CAP_MIN: 30, // радар спальни может продлить выход максимум до N мин
    MORNING_EMPTY_MIN: 3,     // утренний выход: кровать пуста N мин...
    MORNING_ACT_MIN: 5,       // ...и активность вне спальни за последние N мин, и солнце взошло
    MAX_SLEEP_H: 14,          // санитарный предел длительности режима
    OVERRIDE_H: 8,            // окно ручного override
    AWAY_MIN: 5,              // все ушли: presence off N мин -> режим on
    ECHO_MS: 15000            // окно распознавания "эха" собственной записи в свитч
};

const now = Date.now();
const MIN = 60000;

// ---------- доступ к состояниям HA ----------
const ha = global.get('homeassistant');
const states = ha && ha.homeAssistant && ha.homeAssistant.states;
if (!states) {
    node.error('Нет global.homeassistant. Включите "Enable global context store" в конфиге сервера HA.');
    return null;
}
const ent   = id => states[id] || null;
const st    = id => { const e = ent(id); return e ? e.state : null; };
const avail = id => { const s = st(id); return s !== null && s !== 'unavailable' && s !== 'unknown'; };
const isOn  = id => st(id) === 'on';

// ---------- загрузка/инициализация состояния FSM ----------
let S = flow.get('sleepFSM', 'file');
if (!S || typeof S !== 'object' || !S.init) {
    // холодный старт: принимаем текущее положение свитча как истину
    S = {
        init: true,
        state: isOn(CFG.SLEEP_SWITCH) ? 'ASLEEP' : 'AWAKE',
        reason: 'init',
        sleepMode: isOn(CFG.SLEEP_SWITCH),
        candidateSince: null,
        asleepSince: isOn(CFG.SLEEP_SWITCH) ? now : null,
        bedOffSince: null,
        bedOccupied: isOn(CFG.BED),
        bedEmptySince: null,
        lastActivityTs: now,
        awaySince: null,
        overrideUntil: null,
        lastAutoWrite: null,
        log: []
    };
}

const automationsEnable = global.get('automationsEnable', 'file');
const autoOk = (automationsEnable !== false); // undefined трактуем как "разрешено"

const topic = msg.topic || 'tick';

// ---------- активность вне спальни ----------
if (CFG.ACTIVITY.indexOf(topic) !== -1 && msg.payload === 'on') {
    S.lastActivityTs = now;
}

// ---------- занятость кровати с дебаунсом ----------
if (avail(CFG.BED)) {
    if (st(CFG.BED) === 'on') {
        S.bedOffSince = null;
        S.bedOccupied = true;
    } else {
        if (S.bedOffSince === null) S.bedOffSince = now;
        S.bedOccupied = (now - S.bedOffSince) < CFG.BED_GAP_S * 1000;
    }
}
// если мат unavailable — bedOccupied замораживается на последнем значении

const bedOccupied    = S.bedOccupied;
const bedroomLightOn = isOn(CFG.BEDROOM_LIGHT);
const anyoneHome     = isOn(CFG.ANYONE_HOME);

// ---------- ручное переключение (manual override) ----------
let manualEvent = false;
if (topic === CFG.SLEEP_SWITCH) {
    const v = (msg.payload === 'on');
    const echo = S.lastAutoWrite &&
                 S.lastAutoWrite.value === v &&
                 (now - S.lastAutoWrite.ts) < CFG.ECHO_MS;
    if (!echo && v !== S.sleepMode) {
        manualEvent = true;
        S.overrideUntil = now + CFG.OVERRIDE_H * 3600000;
        S.state = v ? 'ASLEEP' : 'AWAKE';
        S.reason = 'manual';
        S.asleepSince = v ? now : null;
        S.candidateSince = null;
        S.bedEmptySince = null;
        S.awaySince = null;
    }
}
if (S.overrideUntil && now > S.overrideUntil) S.overrideUntil = null;
const override = !!S.overrideUntil;

// ---------- скоринг "похоже на ночь" ----------
function isDarkHouse() {
    const e = ent(CFG.ILLUM);
    if (!e) return false;
    // пробуем найти числовой атрибут с люксами
    if (e.attributes) {
        for (const a of CFG.LUX_ATTRS) {
            const v = parseFloat(e.attributes[a]);
            if (!isNaN(v)) return v < CFG.DARK_LUX;
        }
    }
    // ВНИМАНИЕ: проверьте семантику бинарного состояния датчика!
    // Здесь предполагается: on = светло, off = темно.
    return e.state === 'off';
}

const sunBelow  = st(CFG.SUN) === 'below_horizon';
const darkHouse = isDarkHouse();
const quiet     = (now - S.lastActivityTs) > CFG.QUIET_MIN * MIN;
const score     = (sunBelow ? 1 : 0) + (darkHouse ? 1 : 0) + (quiet ? 1 : 0);
const holdMin   = CFG.HOLD_BY_SCORE[score];

// ---------- переходы ----------
let changedTo = null; // true/false если состояние сменилось автоматикой
let cause = null;

if (!manualEvent && autoOk) {

    if (S.state === 'AWAKE') {

        if (!override) {
            // --- кандидат на сон: жёсткие условия ---
            const hardOk = bedOccupied && !bedroomLightOn && anyoneHome;
            if (hardOk) {
                if (S.candidateSince === null) S.candidateSince = now;
                // требуемое удержание пересчитывается каждый тик по текущему скорингу;
                // накопленное время зачитывается
                if ((now - S.candidateSince) >= holdMin * MIN) {
                    S.state = 'ASLEEP'; S.reason = 'sleep';
                    S.asleepSince = now;
                    S.candidateSince = null;
                    changedTo = true;
                    cause = 'sleep (score=' + score + ', hold=' + holdMin + 'm)';
                }
            } else {
                S.candidateSince = null;
            }

            // --- все ушли из дома ---
            if (!anyoneHome) {
                if (S.awaySince === null) S.awaySince = now;
                if (S.state === 'AWAKE' && (now - S.awaySince) >= CFG.AWAY_MIN * MIN) {
                    S.state = 'ASLEEP'; S.reason = 'away';
                    S.asleepSince = now;
                    changedTo = true;
                    cause = 'away';
                }
            } else {
                S.awaySince = null;
            }
        }

    } else if (S.state === 'ASLEEP') {

        // таймер пустой кровати
        if (!bedOccupied) {
            if (S.bedEmptySince === null) S.bedEmptySince = now;
        } else {
            S.bedEmptySince = null;
        }
        const emptyMin = S.bedEmptySince ? (now - S.bedEmptySince) / MIN : 0;
        const radarSeesPerson = avail(CFG.BEDROOM_RADAR) && isOn(CFG.BEDROOM_RADAR);
        const recentActivity = (now - S.lastActivityTs) < CFG.MORNING_ACT_MIN * MIN;

        let exit = null;

        if (S.reason === 'away') {
            // режим включён по уходу: возврат кого-то домой -> мгновенный выход
            if (anyoneHome) exit = 'presence returned';
        } else if (!override) {
            if (bedroomLightOn) {
                exit = 'bedroom light on';
            } else if (emptyMin >= CFG.BED_EMPTY_EXIT_MIN &&
                       (!radarSeesPerson || emptyMin >= CFG.RADAR_EXTEND_CAP_MIN)) {
                // радар лишь продлевает выход, и то с потолком (защита от залипания)
                exit = 'bed empty ' + Math.round(emptyMin) + 'm';
            } else if (!sunBelow && emptyMin >= CFG.MORNING_EMPTY_MIN && recentActivity) {
                // утро: встал без света и ушёл по дому
                exit = 'morning activity';
            }
        }

        // санитарный предел — действует даже в override
        if (!exit && S.asleepSince && (now - S.asleepSince) > CFG.MAX_SLEEP_H * 3600000) {
            exit = 'max duration ' + CFG.MAX_SLEEP_H + 'h';
        }

        if (exit) {
            S.state = 'AWAKE'; S.reason = 'auto';
            S.asleepSince = null;
            S.bedEmptySince = null;
            S.candidateSince = null;
            changedTo = false;
            cause = exit;
        }
    }
}

// ---------- вывод ----------
// out1: включить свитч, out2: выключить свитч, out3: уведомление downstream (payload bool)
const outputs = [null, null, null];
const newMode = (S.state === 'ASLEEP');

if (manualEvent) {
    // свитч уже в нужном положении (переключён человеком) — только уведомляем
    S.sleepMode = newMode;
    global.set('sleepMode', newMode, 'file');
    S.log.unshift(new Date(now).toISOString() + ' MANUAL -> ' + S.state + ' (override ' + CFG.OVERRIDE_H + 'h)');
    outputs[2] = { payload: newMode, topic: 'sleepMode', reason: 'manual' };
} else if (changedTo !== null) {
    S.sleepMode = newMode;
    global.set('sleepMode', newMode, 'file');
    S.lastAutoWrite = { value: newMode, ts: now };
    S.log.unshift(new Date(now).toISOString() + ' AUTO -> ' + S.state + ' (' + cause + ')');
    if (newMode) outputs[0] = { payload: 'on' };
    else         outputs[1] = { payload: 'off' };
    outputs[2] = { payload: newMode, topic: 'sleepMode', reason: cause };
}
if (S.log.length > 30) S.log.length = 30;

flow.set('sleepFSM', S, 'file');

// статус узла для наглядной отладки
const held = S.candidateSince ? Math.round((now - S.candidateSince) / MIN) : null;
node.status({
    fill: newMode ? 'blue' : 'green',
    shape: override ? 'ring' : 'dot',
    text: S.state
        + (held !== null ? ' | кандидат ' + held + '/' + holdMin + 'м' : '')
        + ' | score ' + score
        + (override ? ' | OVERRIDE' : '')
});

return outputs;
